from pathlib import Path
import json,re,subprocess
P=Path(__file__).resolve().parents[1]
# Синхронизация заметок с уточненным историческим графиком.
notes=json.loads((P/'src/notes.json').read_text(encoding='utf-8'))
notes[10]='''На графике разделены длительный этап и отдельные события. Интервью после внедрения подтверждает начало исследований в 2003 году, первый полевой тест в 2008 году и завершение внедрения в 2016 году. Первичный пресс-релиз UPS дополнительно указывает период прототипирования с 2008 по 2011 год и официальный запуск в 2013 году. Поэтому полоса на диаграмме относится только к опубликованному периоду, а ромбы обозначают вехи. Их положение внутри года условно: точные месяцы не установлены. Нельзя автоматически считать весь промежуток между двумя вехами отдельной стадией разработки. В материалах проекта дополнительно сохранен оценочный график одной площадки на семнадцать недель. Он нужен для учебного планирования, но не заменяет историю UPS. В апреле 2016 завершение еще прогнозировалось; сообщение о состоявшемся завершении взято из последующего интервью. Так источники разных лет дополняют, а не подменяют друг друга.'''
(P/'src/notes.json').write_text(json.dumps(notes,ensure_ascii=False,indent=2),encoding='utf-8')
notespath=P/'docs/speaker_notes.md';txt=notespath.read_text(encoding='utf-8');start=txt.index('## Слайд 11\n');end=txt.index('## Слайд 12\n');txt=txt[:start]+'## Слайд 11\n\n**Время:** 09:15–10:15 (60 с, включая короткую паузу).\n\n**Что говорить:**\n\n'+notes[10]+'\n\n'+txt[end:];words=sum(len(n.split()) for n in notes);txt=re.sub(r'Объем произносимого текста: \d+ слов',f'Объем произносимого текста: {words} слов',txt);notespath.write_text(txt,encoding='utf-8')

def doc(name):
    t=(P/'docs'/name).read_text(encoding='utf-8').split('## Sources')[0];t='\n'.join(t.splitlines()[1:]).strip()
    return re.sub(r'(?m)^(#+) ',lambda m:'#'+m[1]+' ',t)
def fig(name,caption):return f'![{caption}](diagrams/rendered/{name}.png)\n\n*{caption}*\n'
arch=doc('architecture.md');life=doc('lifecycle.md');proposal=doc('digital_technology_proposal.md');questions=doc('questions.md');uc=doc('use_case_specification.md')
sections=[
('Тема работы','Анализ внедрения информационной системы оптимизации маршрутов **UPS ORION**: от исходного процесса к требованиям, архитектуре, жизненному циклу и бизнес-эффекту.\n\nРТУ МИРЭА. Дисциплина «Проектирование информационных систем». Практическая / самостоятельная работа № 1. Работу выполнила команда «Байтенки».\n\nВ работе применяются метки **ФАКТ**, **ВЫВОД**, **РЕКОНСТРУКЦИЯ**. Подтвержденная публикация корпоративной оценки не означает независимый аудит. Укрупненные схемы на слайдах и подробные диаграммы проекта описывают одну учебную модель.'),
('Цель','Исследовать реально внедренную ИС на уровне изменения бизнес-процесса; установить автоматизируемое решение; сформировать сопоставимые AS-IS и TO-BE, UML-варианты использования и спецификацию; обосновать логическую архитектуру и подходящий жизненный цикл. Отдельная задача — показать границу проверенного знания и учебных проектных предположений.\n\nМетод: сравнение трех реальных кандидатов; чтение первичных и профессиональных источников; реестр фактов; реконструкция моделей; проверка согласованности диаграмм, отчетных показателей и презентации. Итог защиты — 15 слайдов и текст выступления примерно на 14 минут.'),
('Выбранный бизнес-кейс','Сравнивались UPS ORION, миграция корпоративных ИС Carlsberg на Azure и Smart tasking DHL. Полное сопоставление сохранено в [research/case_selection.md](research/case_selection.md). Для дальнейшего анализа выбран только ORION: доступны ясное операционное решение, сведения о собственной PFT и разработчике, проблемы данных, полевые испытания и оценка бизнес-эффекта.[1]\n\n**ФАКТ.** Первоначальное внедрение ORION завершилось в 2016 году.[1] **РЕКОНСТРУКЦИЯ границы.** Рассматривается дневной маршрут одного водителя: от доступных заданий до выполнения и получения операционных результатов. Распределение всей сети, межгород, сортировка и поздние динамические версии исключены. Это устраняет смешение проектов разных поколений.'),
('Описание предметной области','**Компания:** UPS. **Отрасль:** логистика и доставка отправлений. **Система:** ORION — собственное оптимизационное решение UPS поверх собственной Package Flow Technologies, PFT.[1] **Разработчик:** команда исследования операций UPS; в успехе проекта объединены ИТ и проектирование процессов.[1]\n\n**Пользователи модели:** планировщик, водитель, руководитель доставки. **Заинтересованные стороны:** клиенты, владелец процесса, ИТ и владельцы данных, команда внедрения. Эти роли — учебная классификация участников, а не копия реального перечня прав доступа.\n\n**Ограничения:** требования обслуживания клиентов, точность карт, необходимость сочетать оптимальность со стабильностью маршрута и принятие рекомендаций сотрудниками.[1] Не установлены официальные SLA, СУБД, физическая топология или точные часы работы. Их отсутствие не восполняется вымышленными значениями.'),
('Проблема','**ФАКТ.** Жилые доставки менее плотны, а персонализация усложняет и удорожает обслуживание.[1] **ВЫВОД.** При заданном наборе клиентов необходимо выбирать последовательность, сокращающую пробег без ухудшения обслуживания. Наличие ИС с заданиями еще не означает оптимальность такого выбора.\n\n**ФАКТ.** Покупные карты оказались недостаточно точными; первоначально дефекты входов ошибочно искали в алгоритме. Потребовались работа с правилами и водителями, а крупнейшим вызовом стало управление изменениями.[1] Профессиональная публикация также описывает ранние неудачные полевые попытки и важность участия водителей.[4]\n\nПрослеживаемость: ручной выбор → расчет с ограничениями → проверка пробега; недостаточная точность карт → контроль входов → проверка пригодности; непринятие нового порядка → полевые тесты и обучение → проверка выполнимости. Эти требования и приемочные метрики являются реконструкцией.'),
('AS-IS','**РЕКОНСТРУКЦИЯ процесса до ORION.** PFT предоставляет задания и условия; планировщик проверяет их; водитель уточняет порядок по опыту; выполняет доставки и заборы; при отклонении повторно оценивает порядок и согласовывает действия; сведения о выполнении возвращаются в операционный контур. PFT уже существовала: это не полностью ручной или бумажный процесс.[1]\n\nРучные операции — выбор/уточнение последовательности и согласование исключений. Источники данных — задания, адреса, ограничения PFT. Узкое место — ограниченность сравнения вариантов человеком. Возможные последствия — лишний пробег и задержка; их частоты не опубликованы. Повторная оценка порядка является учебной моделью дублирования решения, а не доказанным повторным вводом адресов.\n\n'+fig('as_is','Рисунок 1. AS-IS, PlantUML Activity Diagram; учебная реконструкция, не BPMN.')+'\nПодробная трассировка фактов и рисков: [case_analysis.md](research/case_analysis.md).'),
('TO-BE','**ФАКТ.** ORION выдает водителю оптимизированную последовательность для заранее назначенных отправлений; профессиональная статья описывает получение такого порядка каждое утро.[4] Собственный оптимизационный контур над PFT и зависимость от точности карт подтверждены интервью.[1]\n\n**РЕКОНСТРУКЦИЯ процесса.** Сохраняются те же входы и границы. Система проверяет пригодность данных, рассчитывает порядок с ограничениями и передает маршрут водителю. Непригодные данные приводят к остановке расчета и ручному разбору. После исправления инициируется новый расчет; при невозможности действует согласованный резервный порядок. Водитель выполняет доставку и с человеком разбирает исключения. Сведения о выполнении закрывают цикл.\n\n'+fig('to_be','Рисунок 2. TO-BE, PlantUML Activity Diagram; учебная реконструкция.')+'\nАвтоматизировано сравнение последовательностей, но не физическая доставка. Непрерывная динамическая перестройка в пути не приписывается первоначальной версии: в интервью 2017 года это дальнейшее развитие.[1]'),
('UML Use Case',fig('use_case','Рисунок 3. UML Use Case; учебная граница ORION.')+'\n'+uc),
('Архитектура ИС',fig('architecture','Рисунок 4. Реконструированная архитектура на основании доступного описания решения.')+'\n'+arch),
('Жизненный цикл','**ФАКТ.** Исследования начались в 2003 году; первый полевой тест состоялся в 2008; завершение внедрения сообщено для 2016 года.[1] UPS дополнительно указывает прототипирование 2008–2011 и официальный запуск 2013.[5]\n\n'+life.split('### 3. Пять стадий учебного жизненного цикла')[-1].split('### 4. Планирование и оценка результата')[0]),
('Модель ЖЦ','**Наиболее подходящая модель ЖЦ для данного проекта:** гибрид итерационной разработки и инкрементального внедрения с критериями готовности. Это проектный вывод, не документированное название методологии UPS.\n\n'+life.split('### 2. Сравнение альтернатив')[-1].split('### 3. Пять стадий учебного жизненного цикла')[0]+'\n'+fig('lifecycle','Рисунок 5. Предлагаемая модель ЖЦ и обратная связь.')),
('График проекта','Проверка источников дала период прототипирования и несколько временных вех. Поэтому основной график построен **по фактическим годам**, без выдуманных календарных дней: 2003 — начало исследований; 2008 — первый полевой тест; 2008–2011 — прототипирование; 2013 — официальный запуск; 2016 — завершение.[1][5]\n\n'+fig('gantt','Рисунок 6. Исторический Гант и вехи с годовой точностью.')+'\nПолоса обозначает только опубликованные годы прототипирования, а ромбы — события. Положение ромба внутри года условно и не обозначает месяц. Промежутки между вехами не заполняются ложными названиями и длительностями стадий. В апреле 2016 завершение являлось прогнозом [5]; после внедрения оно сообщено в интервью [1].\n\nДополнительно сохранены `gantt_estimate.csv` и `gantt_estimate.png`: **«Учебная реконструкция графика проекта. Точные сроки в открытых источниках не опубликованы»**. Это оценка одной площадки, не всей программы UPS: анализ недели 1–3, проектирование 3–6, настройка 6–10, пилот 10–13, обучение 13–15, стабилизация 15–17. Параллельность не требует одинаковых исполнителей; трудоемкость ресурсов не заявлена.'),
('Результаты внедрения','**ФАКТ опубликованного сообщения.** В интервью 2017 года приводится сокращение пробега ORION на 100 млн миль в год и оценка UPS $300–400 млн годовой экономии.[1] Пресс-релиз 2016 использует формулировку «экономия и предотвращенные затраты», причем на тот момент это прогноз полного развертывания.[5] Значения не следует трактовать как прирост чистой прибыли или независимо аудированное измерение.\n\n'+fig('results','Рисунок 7. Было / Стало: показаны изменения, а не выдуманные базовые значения.')+'\nБазовые абсолютные расходы и пробег, сопоставимые для расчета процентов, не опубликованы в использованном интервью. Поэтому не рассчитываются процент сокращения, ROI и окупаемость. Эффект PFT не суммируется с эффектом ORION. Качественный вывод: лучшая последовательность снижает операционные издержки при сохранении задачи обслуживания; причинность и переносимость на другой бизнес требуют собственной проверки.'),
('Сквозная цифровая технология',proposal+'\n'+fig('future_technology','Рисунок 8. Авторское развитие: ML-прогноз времени остановки с неопределенностью.')),
('Вопросы',questions),
('Вывод','Проект UPS ORION показывает, что внедрение ИС — это изменение способа принятия решения внутри уже автоматизированного процесса. В учебной модели сохраняются входные задания и физическая доставка, но сравнение вариантов передается системе; качество данных и обработка исключений остаются обязательными условиями. Успех объясняется сочетанием алгоритма, пригодных данных и организационного внедрения, что согласуется с интервью владельца процесса и профессиональным разбором.[1][4]\n\nСозданы сопоставимые AS-IS/TO-BE, UML и спецификация, реконструированная архитектура, обоснованная модель ЖЦ, исторический график и отдельный оценочный план площадки. Для дальнейшего развития предложен проверяемый ML-контур, не обещающий заранее заданной экономии. Факты, выводы и реконструкции разграничены, что позволяет защищать работу без утверждений об неизвестной внутренней инфраструктуре UPS.'),
('Источники','Полная аннотированная библиография, ограничения и сведения об архивной копии: [research/sources.md](research/sources.md). Основной анализ опирается на интервью UPS, профессиональную публикацию INFORMS и пресс-релиз UPS. Остальные материалы служат только выбору кандидата.\n\n## Sources\n')]
report='# Практическая работа № 1. Проектирование информационных систем\n\n'+'\n\n'.join(f'## {i}. {h}\n\n{t}' for i,(h,t) in enumerate(sections,1))
(P/'Практическая_работа_1.md').write_text(report,encoding='utf-8')
S=P/'src/citations/sources.py';cmd=['python3',str(S),'--ledger',str(P/'research/ledger.json')]
for p in [P/'Практическая_работа_1.md',P/'research/sources.md']:
    subprocess.run(cmd+['render','--replace-in',str(p)],check=True)
print(json.dumps({'report_sections':len(sections),'speaker_words':words,'reading_minutes_at_130':round(words/130,2)},ensure_ascii=False))
